package org.strongswan.android.rookstride;
import org.json.*;import org.junit.Test;import java.io.*;import java.nio.file.*;import java.util.*;import static org.junit.Assert.*;
public final class ArtifactBridgeTest {
    static final class Source implements ArtifactBridge.Source {
        final PublicArtifactCatalog catalog;final File cache;final ArtifactDownloaderTest.Transport http=new ArtifactDownloaderTest.Transport();int transports;
        Source()throws Exception{catalog=PublicArtifactCatalogTest.catalog();cache=ArtifactDownloaderTest.directory();}
        public PublicArtifactCatalog catalog(){return catalog;}public File cacheDirectory(){return cache;}public InputStream openBundle(){throw new AssertionError("Pure bridge must not open an SSH bundle");}public ArtifactDownloader.Transport transport(){transports++;return http;}
    }
    static final class Endpoint implements ArtifactBridge.Endpoint {
        final Source source;final String machine;String architecture="x86_64";boolean ready,reuse,loseCommit,commitReady=true,wrongCatalog,wrongCommitMachine,wrongCommitId,interruptCommit,peerUnavailable,corruptPeer,notRoot;int uploads,cleans,commits,statuses,reads;final List<JSONObject> requests=new ArrayList<>();
        Endpoint(Source s,char identity){source=s;char[] value=new char[64];Arrays.fill(value,identity);machine=new String(value);}
        public JSONObject identity()throws Exception{return new JSONObject().put("machine",machine).put("architecture",architecture).put("cache_readable",!notRoot);}
        public JSONObject request(JSONObject request)throws Exception{
            requests.add(new JSONObject(request.toString()));JSONObject r=ArtifactBridge.base(source.catalog,identity(),request.getString("action"));r.remove("action");if(wrongCatalog)r.put("catalog_sha256",new String(new char[64]).replace('\0','f'));
            if(request.getString("action").equals("prepare")){JSONArray ids=request.getJSONArray("ids");r.put("ready",ready?ids:new JSONArray()).put("phone_required",!ready&&!reuse?ids:new JSONArray()).put("reused",reuse?ids:new JSONArray());}
            else if(request.getString("action").equals("commit")){commits++;ready=commitReady;if(loseCommit)throw new ArtifactBridge.UnknownResult(new EOFException());r.put("ready",ready).put("id",request.getString("id"));if(wrongCommitMachine)r.put("machine",new String(new char[64]).replace('\0','c'));if(wrongCommitId)r.put("id","adguard");if(interruptCommit)Thread.currentThread().interrupt();}
            else if(request.getString("action").equals("status")){statuses++;r.put("ready",ready).put("id",request.getString("id"));}else throw new AssertionError("No install/user RPC is allowed");return r;
        }
        public void upload(PublicArtifactCatalog.Asset asset,String nonce,File file)throws Exception{ArtifactDownloader.verify(file,asset);assertTrue(nonce.matches("[a-f0-9]{32}"));uploads++;}
        public InputStream cached(PublicArtifactCatalog.Asset asset)throws Exception{reads++;if(peerUnavailable)throw new ArtifactBridge.PeerUnavailable(new IOException("permission"));return new ByteArrayInputStream(corruptPeer?new byte[PublicArtifactCatalogTest.BYTES.length]:PublicArtifactCatalogTest.BYTES);}
        public void clean(String nonce,String id){cleans++;}public void close(){}
    }
    private interface Checked{void run()throws Exception;}
    private static void refuses(Checked action)throws Exception{try{action.run();fail("The unsafe pre-job boundary was accepted");}catch(IOException expected){}}
    @Test public void serverVerifiedCacheNeverStartsPhoneNetworkOrSftp()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.ready=true;ArtifactBridge.prepare(s,target,null,Arrays.asList("adguard","xray"));assertEquals(0,s.transports);assertEquals(0,target.uploads);assertEquals(1,target.requests.size());}
    @Test public void completeInstalledFilterReuseDoesNotRequireAnyArchive()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.reuse=true;ArtifactBridge.prepare(s,target,null,Collections.singletonList("adguard"));assertEquals(0,s.transports);assertEquals(0,target.uploads);assertTrue(target.requests.get(0).getBoolean("reuse_installed"));}
    @Test public void serverTransportFailureFetchesAndUploadsOnlyPinnedBytesBeforeCompletion()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');s.http.replies.add(ArtifactDownloaderTest.reply());ArtifactBridge.prepare(s,target,null,Collections.singletonList("adguard"));assertEquals(1,s.transports);assertEquals(1,target.uploads);assertEquals(1,target.commits);assertEquals(1,target.cleans);assertEquals("commit",target.requests.get(1).getString("action"));}
    @Test public void sameArchitecturePeerPrecedesPhoneHttpsAndIsIndependentlyVerified()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a'),peer=new Endpoint(s,'b');peer.ready=true;ArtifactBridge.prepare(s,target,peer,Collections.singletonList("xray"));assertEquals(0,s.transports);assertEquals(1,peer.reads);assertEquals(1,target.uploads);assertFalse(peer.requests.get(0).getBoolean("reuse_installed"));}
    @Test public void differentArchitecturePeerIsNotAcquiredOrRead()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a'),peer=new Endpoint(s,'b');peer.architecture="aarch64";s.http.replies.add(ArtifactDownloaderTest.reply());ArtifactBridge.prepare(s,target,peer,Collections.singletonList("xray"));assertEquals(1,s.transports);assertTrue(peer.requests.isEmpty());assertEquals(0,peer.reads);}
    @Test public void nonRootPeerNeverAcquiresOrReadsPublicCache()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a'),peer=new Endpoint(s,'b');peer.notRoot=true;s.http.replies.add(ArtifactDownloaderTest.reply());ArtifactBridge.prepare(s,target,peer,Collections.singletonList("xray"));assertTrue(peer.requests.isEmpty());assertEquals(0,peer.reads);assertEquals(1,s.transports);}
    @Test public void unreadablePeerFallsBackButCorruptPeerNeverDoes()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a'),peer=new Endpoint(s,'b');peer.ready=true;peer.peerUnavailable=true;s.http.replies.add(ArtifactDownloaderTest.reply());ArtifactBridge.prepare(s,target,peer,Collections.singletonList("xray"));assertEquals(1,s.transports);Source bad=new Source();Endpoint t=new Endpoint(bad,'a'),p=new Endpoint(bad,'b');p.ready=true;p.corruptPeer=true;refuses(()->ArtifactBridge.prepare(bad,t,p,Collections.singletonList("xray")));assertEquals(0,bad.transports);assertEquals(0,t.uploads);}
    @Test public void lostCommitAcknowledgementUsesOnlyReadOnlyStatusAndNeverReuploads()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.loseCommit=true;s.http.replies.add(ArtifactDownloaderTest.reply());ArtifactBridge.prepare(s,target,null,Collections.singletonList("xray"));assertEquals(1,target.commits);assertEquals(1,target.statuses);assertEquals(1,target.uploads);assertEquals(1,target.cleans);}
    @Test public void unconfirmedCommitRetainsUploadAndNeverRetriesAnInstallOrCommit()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.loseCommit=true;target.commitReady=false;s.http.replies.add(ArtifactDownloaderTest.reply());refuses(()->ArtifactBridge.prepare(s,target,null,Collections.singletonList("xray")));assertEquals(1,target.commits);assertEquals(1,target.statuses);assertEquals(0,target.cleans);}
    @Test public void catalogAndAcknowledgementIdentityMismatchAreFatalRatherThanStatusMasked()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.wrongCatalog=true;refuses(()->ArtifactBridge.prepare(s,target,null,Collections.singletonList("xray")));assertEquals(0,s.transports);assertEquals(0,target.uploads);Source second=new Source();Endpoint changed=new Endpoint(second,'a');changed.wrongCommitMachine=true;second.http.replies.add(ArtifactDownloaderTest.reply());refuses(()->ArtifactBridge.prepare(second,changed,null,Collections.singletonList("xray")));assertEquals(0,changed.statuses);assertEquals(0,changed.cleans);}
    @Test public void acknowledgementForAnotherComponentCannotMaskTheSelectedArchive()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.wrongCommitId=true;s.http.replies.add(ArtifactDownloaderTest.reply());refuses(()->ArtifactBridge.prepare(s,target,null,Collections.singletonList("xray")));assertEquals(0,target.statuses);assertEquals(0,target.cleans);}
    @Test public void cancellationDuringFinalCommitStopsAtTheActualDispatchGuard()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');target.interruptCommit=true;s.http.replies.add(ArtifactDownloaderTest.reply());try{ArtifactBridge.prepare(s,target,null,Collections.singletonList("xray"));refuses(()->ArtifactBridge.beforeDispatch());assertEquals(1,target.commits);}finally{Thread.interrupted();}}
    @Test public void localVerifiedArchiveWorksWithoutPhoneNetworkAndBadArchiveIsPreserved()throws Exception{Source s=new Source();Endpoint target=new Endpoint(s,'a');PublicArtifactCatalog.Asset a=s.catalog.asset("xray","x86_64");Files.write(new File(s.cache,a.sha256).toPath(),PublicArtifactCatalogTest.BYTES);ArtifactBridge.prepare(s,target,null,Collections.singletonList("xray"));assertEquals(0,s.transports);assertEquals(1,target.uploads);}
    @Test public void pollingUserCrudAndRecoveryDoNotAcquirePublicSoftware()throws Exception{for(String kind:new String[]{"single","pair","recovery","engine-update"})for(String action:new String[]{"status","job","inspect","profile","add-user","edit-user","remove-user","restore","rehearse-pair"})assertTrue(ArtifactBridge.required(kind,new JSONObject().put("action",action).put("command",action)).isEmpty());assertTrue(ArtifactBridge.required("deploy",new JSONObject().put("mode","enroll")).isEmpty());}
    @Test public void singleRetryAndRebuiltPairBootstrapSelectOnlyActualConsumers()throws Exception{assertEquals(Arrays.asList("adguard","xray"),ArtifactBridge.required("single",new JSONObject().put("action","retry").put("request",new JSONObject().put("protocol","xhttp"))));assertEquals(Collections.singletonList("adguard"),ArtifactBridge.required("single",new JSONObject().put("action","start").put("protocol","awg")));JSONObject pair=new JSONObject().put("command","start").put("action","bootstrap").put("engine","native-v2").put("entry_protocol","awg").put("exit_protocol","awg").put("role","entry");assertTrue(ArtifactBridge.required("pair",pair).isEmpty());pair.put("role","exit");assertEquals(Collections.singletonList("adguard"),ArtifactBridge.required("pair",pair));pair.put("role","entry").put("exit_protocol","xray");assertEquals(Collections.singletonList("xray"),ArtifactBridge.required("pair",pair));pair.put("entry_protocol","awg").put("exit_protocol","trusttunnel");assertTrue(ArtifactBridge.required("pair",pair).isEmpty());pair.put("entry_protocol","trusttunnel").put("exit_protocol","awg");assertEquals(Collections.singletonList("trusttunnel"),ArtifactBridge.required("pair",pair));pair.put("role","exit").put("exit_protocol","trusttunnel");assertEquals(Arrays.asList("adguard","trusttunnel"),ArtifactBridge.required("pair",pair));assertEquals(Arrays.asList("adguard","trusttunnel"),ArtifactBridge.required("single",new JSONObject().put("action","start").put("protocol","trusttunnel")));}
}
